#include "nds_loader.h"
namespace dsfex360 {namespace {
NdsLoadResult fail(LoaderError e){NdsLoadResult r={};r.error=e;return r;}
bool fits(std::uint32_t o,std::uint32_t s,std::size_t n){return s&&o<n&&std::uint64_t(o)+s<=n;}
LoadedSection copy(const std::vector<std::uint8_t>&rom,std::uint32_t o,std::uint32_t s,std::uint32_t entry,std::uint32_t load){LoadedSection r={};r.entry_address=entry;r.load_address=load;r.bytes.assign(rom.begin()+o,rom.begin()+o+s);return r;}}
NdsLoadResult load_nds_sections(const std::vector<std::uint8_t>&rom){auto p=parse_nds_header(rom);if(!p.ok())return fail(LoaderError::InvalidHeader);const auto&h=p.header;if(!fits(h.arm9_rom_offset,h.arm9_size,rom.size()))return fail(LoaderError::Arm9CopyRangeInvalid);if(!fits(h.arm7_rom_offset,h.arm7_size,rom.size()))return fail(LoaderError::Arm7CopyRangeInvalid);NdsLoadResult r={};r.error=LoaderError::None;r.header=h;r.arm9=copy(rom,h.arm9_rom_offset,h.arm9_size,h.arm9_entry_address,h.arm9_load_address);r.arm7=copy(rom,h.arm7_rom_offset,h.arm7_size,h.arm7_entry_address,h.arm7_load_address);return r;}
LoaderError load_nds_into_memory(const NdsLoadResult&r,AddressSpace&m){if(!r.ok())return LoaderError::InvalidHeader;if(!m.can_write(r.arm9.load_address,r.arm9.bytes.size()))return LoaderError::Arm9DestinationInvalid;if(!m.can_write(r.arm7.load_address,r.arm7.bytes.size()))return LoaderError::Arm7DestinationInvalid;if(!m.write(r.arm9.load_address,r.arm9.bytes.data(),r.arm9.bytes.size()))return LoaderError::MemoryWriteFailed;if(!m.write(r.arm7.load_address,r.arm7.bytes.data(),r.arm7.bytes.size()))return LoaderError::MemoryWriteFailed;return LoaderError::None;}
const char*loader_error_message(LoaderError e){switch(e){case LoaderError::None:return "no error";case LoaderError::InvalidHeader:return "invalid Nintendo DS ROM header";case LoaderError::Arm9CopyRangeInvalid:return "ARM9 payload range cannot be copied";case LoaderError::Arm7CopyRangeInvalid:return "ARM7 payload range cannot be copied";case LoaderError::Arm9DestinationInvalid:return "ARM9 destination is not mapped";case LoaderError::Arm7DestinationInvalid:return "ARM7 destination is not mapped";case LoaderError::MemoryWriteFailed:return "failed to write CPU payload to memory";}return "unknown error";}}
